style.css:
@-moz-document domain("roblox.com") {
/* --- Background Image --- */
  body {
    background: url(https://i.pinimg.com/736x/b6/80/79/b68079eb579bf1766821d70df58687a4.jpg) no-repeat center center fixed !important;
    background-size: cover !important;
    color: #333 !important;
  }

  /* --- Main Containers --- */
  .content, .container-main, .navbar, .footer, .game-card, .section-content, .section {
    background-color: rgba(255, 255, 255, 0.8) !important;
    border-radius: 8px !important;
    backdrop-filter: blur(5px);
  }

  /* --- Text Colors --- */
  h1, h2, h3, h4, h5, h6, p, a, span, div {
    color: #222 !important;
  }

  /* --- Buttons --- */
  button, .btn-primary, .btn-secondary {
    background-color: #ddd !important;
    color: #222 !important;
    border: 1px solid #aaa !important;
  }

  button:hover, .btn-primary:hover, .btn-secondary:hover {
    background-color: #ccc !important;
  }

  /* --- Header & Footer --- */
  header, footer, .nav-container {
    background-color: rgba(245, 245, 245, 0.85) !important;
    border-bottom: 1px solid #ccc !important;
  }

  /* --- Scrollbar --- */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #aaa;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background-color: #888;
  }
}
